import Foundation

/// `golden_vectors.json`, the one conformance fixture, as typed Swift values.
///
/// The same file pins the C# suite. It is generated by `tools/golden_vectors.py`,
/// whose checksum implementation is checked against the four published XXH32
/// reference vectors before it writes anything. So when Swift and C# agree here
/// they are agreeing with an outside source, not merely with each other.
///
/// Decoded with `JSONDecoder` rather than `JSONSerialization` on purpose: the U2
/// vector carries a timestamp of 2^64 − 1, and the untyped route hands that back
/// as a `Double` that has already lost the low bits.
struct GoldenVectors: Decodable {
    struct GenericChecksum: Decodable {
        let dataHex: String
        let seed: String
        let expect: String

        enum CodingKeys: String, CodingKey {
            case dataHex = "data_hex"
            case seed, expect
        }
    }

    struct FixedChecksum: Decodable {
        let name: String
        let dataHex: String
        let expect: String

        enum CodingKeys: String, CodingKey {
            case dataHex = "data_hex"
            case name, expect
        }
    }

    struct UplinkFields: Decodable {
        let seq: UInt16
        let steer: Int16
        let throttle: UInt16
        let brake: UInt16
        let clutch: UInt16
        let buttons: UInt32
        let tsNs: UInt64

        enum CodingKeys: String, CodingKey {
            case tsNs = "ts_ns"
            case seq, steer, throttle, brake, clutch, buttons
        }
    }

    struct UplinkVector: Decodable {
        let name: String
        let fields: UplinkFields
        let hex: String
        let checksum: String
    }

    struct DownlinkFields: Decodable {
        let rpm: UInt16
        let absActive: Int
        let tcActive: Int
        let slip: Double

        enum CodingKeys: String, CodingKey {
            case absActive = "abs_active"
            case tcActive = "tc_active"
            case rpm, slip
        }
    }

    struct DownlinkVector: Decodable {
        let name: String
        let fields: DownlinkFields
        let hex: String
    }

    struct TwistVector: Decodable {
        let name: String
        let qRef: [Double]
        let qCur: [Double]
        let thetaDeg: Double
        let naiveProjectionDeg: Double
        let dorDeg: Double
        let deadband: Double
        let gamma: Double
        let steerNorm: Double
        let steerI16: Int

        enum CodingKeys: String, CodingKey {
            case qRef = "q_ref"
            case qCur = "q_cur"
            case thetaDeg = "theta_deg"
            case naiveProjectionDeg = "naive_projection_deg"
            case dorDeg = "dor_deg"
            case steerNorm = "steer_norm"
            case steerI16 = "steer_i16"
            case name, deadband, gamma
        }
    }

    struct UnwrapVector: Decodable {
        let name: String
        let sequenceDeg: [Double]
        let continuousDeg: Double
        let dorDeg: Double
        let steerNorm: Double
        let steerI16: Int

        enum CodingKeys: String, CodingKey {
            case sequenceDeg = "sequence_deg"
            case continuousDeg = "continuous_deg"
            case dorDeg = "dor_deg"
            case steerNorm = "steer_norm"
            case steerI16 = "steer_i16"
            case name
        }
    }

    struct SteerMapVector: Decodable {
        let thetaContDeg: Double
        let dorDeg: Double
        let deadband: Double
        let gamma: Double
        let steerNorm: Double
        let steerI16: Int

        enum CodingKeys: String, CodingKey {
            case thetaContDeg = "theta_cont_deg"
            case dorDeg = "dor_deg"
            case steerNorm = "steer_norm"
            case steerI16 = "steer_i16"
            case deadband, gamma
        }
    }

    struct NormVector: Decodable {
        let norm: Double
        let steerI16: Int

        enum CodingKeys: String, CodingKey {
            case steerI16 = "steer_i16"
            case norm
        }
    }

    struct ShapeVector: Decodable {
        let x: Double
        let deadband: Double
        let gamma: Double
        let y: Double
    }

    struct Sizes: Decodable {
        let uplink: Int
        let downlink: Int
    }

    struct ChecksumMeta: Decodable {
        let algorithm: String
        let seed: String
        let coveredBytes: Int
        let storedAtOffset: Int

        enum CodingKeys: String, CodingKey {
            case coveredBytes = "covered_bytes"
            case storedAtOffset = "stored_at_offset"
            case algorithm, seed
        }
    }

    let sizes: Sizes
    let checksum: ChecksumMeta
    let xxh32Generic: [GenericChecksum]
    let xxh3228: [FixedChecksum]
    let uplink: [UplinkVector]
    let downlink: [DownlinkVector]
    let twist: [TwistVector]
    let unwrap: UnwrapVector
    let steerMap: [SteerMapVector]
    let steerI16FromNorm: [NormVector]
    let shape: [ShapeVector]

    enum CodingKeys: String, CodingKey {
        case xxh32Generic = "xxh32_generic"
        case xxh3228 = "xxh32_28"
        case steerMap = "steer_map"
        case steerI16FromNorm = "steer_i16_from_norm"
        case sizes, checksum, uplink, downlink, twist, unwrap, shape
    }

    static let shared: GoldenVectors = {
        guard let url = Bundle.module.url(forResource: "golden_vectors",
                                          withExtension: "json") else {
            fatalError("golden_vectors.json is missing from the test bundle. "
                     + "Check the resources list in Package.swift.")
        }
        do {
            let data = try Data(contentsOf: url)
            return try JSONDecoder().decode(GoldenVectors.self, from: data)
        } catch {
            fatalError("could not decode golden_vectors.json: \(error)")
        }
    }()
}

// MARK: - small shared helpers

/// "52 54 53 4f" and "5254534f" are both accepted; the fixture uses both forms.
func goldenHex(_ text: String) -> [UInt8] {
    let compact = text.replacingOccurrences(of: " ", with: "")
    precondition(compact.count % 2 == 0, "odd-length hex string: \(text)")

    var bytes: [UInt8] = []
    bytes.reserveCapacity(compact.count / 2)

    var index = compact.startIndex
    while index < compact.endIndex {
        let next = compact.index(index, offsetBy: 2)
        guard let byte = UInt8(compact[index..<next], radix: 16) else {
            preconditionFailure("not hex: \(compact[index..<next])")
        }
        bytes.append(byte)
        index = next
    }
    return bytes
}

/// The fixture stores 32-bit values as "0xF4FDFD7A".
func goldenU32(_ text: String) -> UInt32 {
    let trimmed = text.hasPrefix("0x") || text.hasPrefix("0X")
        ? String(text.dropFirst(2))
        : text
    guard let value = UInt32(trimmed, radix: 16) else {
        preconditionFailure("not a 32-bit hex literal: \(text)")
    }
    return value
}

/// Renders bytes the way the fixture does, so a failure message can be pasted
/// straight into a diff against the JSON.
func hexString(_ bytes: [UInt8]) -> String {
    bytes.map { String(format: "%02x", $0) }.joined(separator: " ")
}
